INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0014-000000000000','쿠버네티스(Kubernetes)란 무엇이며, 어떤 문제를 해결하기 위해 등장했나요?','EASY','b0000000-0000-0000-0000-000000000014'),
('b0000000-0000-0000-0014-000000000001','쿠버네티스의 주요 구성 요소는 무엇인가요? (예: Master Node, Worker Node)','EASY','b0000000-0000-0000-0000-000000000014'),
('b0000000-0000-0000-0014-000000000002','Pod란 무엇인가요?','EASY','b0000000-0000-0000-0000-000000000014'),
('b0000000-0000-0000-0014-000000000003','Deployment와 Service의 차이는 무엇인가요?','EASY','b0000000-0000-0000-0000-000000000014'),
('b0000000-0000-0000-0014-000000000004','컨테이너 오케스트레이션 도구로서 Kubernetes의 장점은 무엇인가요?','MEDIUM','b0000000-0000-0000-0000-000000000014'),
('b0000000-0000-0000-0014-000000000005','Kubernetes에서 Namespace는 무엇이며 왜 사용하나요?','MEDIUM','b0000000-0000-0000-0000-000000000014'),
('b0000000-0000-0000-0014-000000000006','쿠버네티스에서 파드(Pod)를 재시작하거나 대체하는 메커니즘은 무엇인가요?','MEDIUM','b0000000-0000-0000-0000-000000000014'),
